import React from "react";

function ResumePreview({ data }) {
  return (
    <div className="space-y-2">

      <h2 className="text-xl font-bold">{data.name}</h2>
      <p className="text-gray-300">{data.email}</p>

      <h3 className="mt-3 font-semibold">Summary</h3>
      <p className="text-gray-400">{data.summary}</p>

      <h3 className="mt-3 font-semibold">Skills</h3>
      <div className="flex flex-wrap gap-2 mt-1">
        {data.skills.split(/[, ]+/).map((s, i) => (
          <span key={i} className="bg-blue-600 px-2 py-1 rounded text-sm">
            {s}
          </span>
        ))}
      </div>

    </div>
  );
}

export default ResumePreview;
